	if err != nil {
		return nil, false, nil, fmt.Errorf("acquire state lock: %w", err)
	}

	gate.mu.Lock()
	gate.owner = gid
	gate.depth = 1
	gate.flockRel = flockRel
	gate.mu.Unlock()

	return gate, true, func() {
		gate.mu.Lock()
		gate.depth--
